mapper.select:

SELECT #{push} AS time,service AS type,SUM(sum) AS num
FROM NTC_SERVICE_REPORT
WHERE report_time>= #{start}
AND report_time< #{end}
GROUP BY type;


	    SELECT SUM(MONITOR_NUM) AS visitsNum,SUM(REJECT_NUM) AS controlNum,SUM(REPLACE_NUM) AS replaceNum
        FROM pxy_total_report
        WHERE REPORT_TIME >= #{start}
           AND REPORT_TIME < #{end}


SELECT #{push} AS time,ACCOUNT AS account,NAS_IP AS nas_ip,SUM(num) AS num
FROM ntc_radius_report
WHERE report_time >= #{start}
    AND report_time < #{end}
GROUP BY account ,nas_ip
ORDER BY num DESC
LIMIT 100;


        SELECT b.name AS name ,a.num AS num,#{push} AS time FROM
        (SELECT cfg_id AS cfgId,SUM(sum) AS num
        FROM ntc_pz_report
        WHERE report_time > #{start}
            AND report_time < #{end}
            AND service = #{serviceId}
        GROUP BY cfgId) a
        LEFT JOIN
	    (SELECT compile_id as compileId,cfg_desc as name FROM ui_cfg_index_info) b
	    on a.cfgId = b.compileId


SELECT report_time
FROM  ntc_pz_report
WHERE REPORT_TIME < #{end}
    AND service = #{serviceId}
ORDER BY report_time DESC
LIMIT 1
